package org.jsoup.nodes;

import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import java.util.Map;
import org.jsoup.SerializationException;
import org.jsoup.helper.Validate;
import org.jsoup.internal.StringUtil;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class Attribute_setValue_TriageGen0Test {

    private Attributes mockParent;
    private Attribute attribute;

    @Before
    public void setUp() {
        mockParent = mock(Attributes.class);
        attribute = new Attribute("key", "value", mockParent);
    }

    @Test
    public void testSetValueWithNonNullParentAndExistingKey() throws Exception {
        when(mockParent.get("key")).thenReturn("oldValue");
        when(mockParent.indexOfKey("key")).thenReturn(0);

        String oldValue = attribute.setValue("newValue");

        verify(mockParent, times(1)).vals[0] = "newValue";
        assertEquals("oldValue", oldValue);
        assertEquals("newValue", attribute.getValue());
    }

    @Test
    public void testSetValueWithNonNullParentAndNonExistingKey() throws Exception {
        when(mockParent.get("key")).thenReturn(null);
        when(mockParent.indexOfKey("key")).thenReturn(Attribute.NotFound);

        String oldValue = attribute.setValue("newValue");

        verify(mockParent, never()).vals[anyInt()] = anyString();
        assertNull(oldValue);
        assertEquals("newValue", attribute.getValue());
    }

    @Test
    public void testSetValueWithNullParent() throws Exception {
        attribute = new Attribute("key", "value", null);

        String oldValue = attribute.setValue("newValue");

        verify(mockParent, never()).vals[anyInt()] = anyString();
        assertEquals("value", oldValue);
        assertEquals("newValue", attribute.getValue());
    }

    @Test
    public void testSetValueWithNullValue() throws Exception {
        when(mockParent.get("key")).thenReturn("oldValue");
        when(mockParent.indexOfKey("key")).thenReturn(0);

        String oldValue = attribute.setValue(null);

        verify(mockParent, times(1)).vals[0] = "null";
        assertEquals("oldValue", oldValue);
        assertEquals("null", attribute.getValue());
    }

    @Test
    public void testSetValueWithNullOldValue() throws Exception {
        when(mockParent.get("key")).thenReturn(null);
        when(mockParent.indexOfKey("key")).thenReturn(0);

        String oldValue = attribute.setValue("newValue");

        verify(mockParent, times(1)).vals[0] = "newValue";
        assertNull(oldValue);
        assertEquals("newValue", attribute.getValue());
    }

    @Test
    public void testSetValueWithKeyValueNull() throws Exception {
        attribute = new Attribute("key", null, mockParent);

        String oldValue = attribute.setValue("newValue");

        verify(mockParent, never()).vals[anyInt()] = anyString();
        assertNull(oldValue);
        assertEquals("newValue", attribute.getValue());
    }
}
